import Foundation
import SwiftUI

/// World layout generated by art/bloom/sprites.py (bloom_world.json).
struct BloomWorld: Decodable {
    struct Island: Decodable {
        let id: Int
        let name: String
        let price: Int
        let cells: [[Int]]
        let origin: [Int]
        let spawn: [String: Int]
        let cap: Int
    }
    struct Bridge: Decodable {
        let tile: [Int]
        let vertical: Bool
        let a: Int
        let b: Int
    }
    let tile: Int
    let islands: [Island]
    let bridges: [Bridge]

    static func load() -> BloomWorld {
        guard let url = Bundle.main.url(forResource: "bloom_world", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let w = try? JSONDecoder().decode(BloomWorld.self, from: data) else {
            fatalError("bloom_world.json missing")
        }
        return w
    }
}

struct Cell: Hashable, Codable {
    var x: Int
    var y: Int
}

struct PlacedBuilding: Codable, Hashable {
    var kind: BuildKind
    var cell: Cell
}

/// One crafting queue per building kind. Items come out one by one.
struct CraftQueue: Codable {
    var recipe: String
    var left: Int
    var progress: Double   // seconds into the current item
}

struct BloomSave: Codable {
    var inv: [String: Int] = [:]
    var coins = 0
    var xp = 0
    var level = 1
    var owned: [Int] = [0]
    var buildings: [PlacedBuilding] = []
    var pick = 0
    var lucky = false
    var queues: [String: CraftQueue] = [:]
    var stats: [String: Int] = [:]
    var goal = 0
    var helpers: [String] = []
    var talents: [String] = []
    var finds: [String: Int] = [:]
    var savedAt = Date()

    init() {}

    /// Tolerant decoding: fields added later default instead of wiping the save.
    init(from d: Decoder) throws {
        let c = try d.container(keyedBy: CodingKeys.self)
        inv = try c.decodeIfPresent([String: Int].self, forKey: .inv) ?? [:]
        coins = try c.decodeIfPresent(Int.self, forKey: .coins) ?? 0
        xp = try c.decodeIfPresent(Int.self, forKey: .xp) ?? 0
        level = try c.decodeIfPresent(Int.self, forKey: .level) ?? 1
        owned = try c.decodeIfPresent([Int].self, forKey: .owned) ?? [0]
        buildings = try c.decodeIfPresent([PlacedBuilding].self, forKey: .buildings) ?? []
        pick = try c.decodeIfPresent(Int.self, forKey: .pick) ?? 0
        lucky = try c.decodeIfPresent(Bool.self, forKey: .lucky) ?? false
        queues = try c.decodeIfPresent([String: CraftQueue].self, forKey: .queues) ?? [:]
        stats = try c.decodeIfPresent([String: Int].self, forKey: .stats) ?? [:]
        goal = try c.decodeIfPresent(Int.self, forKey: .goal) ?? 0
        helpers = try c.decodeIfPresent([String].self, forKey: .helpers) ?? []
        talents = try c.decodeIfPresent([String].self, forKey: .talents) ?? []
        finds = try c.decodeIfPresent([String: Int].self, forKey: .finds) ?? [:]
        savedAt = try c.decodeIfPresent(Date.self, forKey: .savedAt) ?? Date()
    }
}

enum BloomPanel: Equatable {
    case build
    case building(BuildKind)
    case buy(Int)
    case inventory
    case talents
    case album
}

struct BloomToast: Identifiable, Equatable {
    let id = UUID()
    let title: String
    let subtitle: String
}

/// Game state and rules. The scene drives it; the HUD observes it.
@MainActor
final class BloomGame: ObservableObject {
    let world = BloomWorld.load()

    /// Not @Published: crafting progress ticks every frame, the HUD must only
    /// redraw on real changes, so `s` publishes from willSet and progress lives apart.
    private(set) var s = BloomSave() { willSet { objectWillChange.send() } }
    /// Seconds into the current item of each queue (not published).
    private(set) var progress: [String: Double] = [:]
    @Published var panel: BloomPanel?
    @Published var combo = 0           // hits in the current chain
    @Published var toast: BloomToast?
    /// What the left context button offers right now (set by the scene).
    @Published var nearby: Nearby?

    enum Nearby: Equatable {
        case building(BuildKind)
        case island(Int)
    }

    /// Scene callbacks.
    var onIslandBought: ((Int) -> Void)?
    var onBuildingPlaced: ((PlacedBuilding) -> Void)?
    var onCrafted: ((BuildKind, BItem, Bool) -> Void)?
    var onGoalClaimed: (() -> Void)?
    var onHelperAdded: ((String) -> Void)?
    var placeBuilding: ((BuildKind) -> Cell?)?

    private let key = "bloom.save.v2"
    private var lastHit: TimeInterval = 0

    init() {
        let args = ProcessInfo.processInfo.arguments
        if args.contains("-bloomReset") { UserDefaults.standard.removeObject(forKey: key) }
        if let d = UserDefaults.standard.data(forKey: key), let v = try? JSONDecoder().decode(BloomSave.self, from: d) {
            s = v
            for (k, q) in v.queues { progress[k] = q.progress }
            catchUp(seconds: Date().timeIntervalSince(v.savedAt))
        }
        if args.contains("-bloomRich") {
            for i in BItem.allCases { s.inv[i.rawValue, default: 0] += 40 }
            s.coins += 1000
            s.level = max(s.level, 4)
        }
    }

    // MARK: - inventory

    func count(_ i: BItem) -> Int { s.inv[i.rawValue] ?? 0 }
    var coins: Int { s.coins }
    var level: Int { s.level }
    var xp: Int { s.xp }
    var xpNeed: Int { BloomContent.xpToNext(s.level) }
    var pickTier: Int { s.pick }
    var pickLucky: Bool { s.lucky }
    var damage: Int {
        BloomContent.picks[s.pick].damage + (s.lucky ? 1 : 0) + (hasT("d1") ? 1 : 0) + (pageDone(2) ? 1 : 0)
    }
    var owned: Set<Int> { Set(s.owned) }
    var buildings: [PlacedBuilding] { s.buildings }

    func has(_ c: Cost, times: Int = 1) -> Bool { c.allSatisfy { count($0.0) >= $0.1 * times } }
    private func pay(_ c: Cost, times: Int = 1) { for (i, n) in c { s.inv[i.rawValue, default: 0] -= n * times } }

    func add(_ i: BItem, _ n: Int) {
        s.inv[i.rawValue, default: 0] += n
        s.stats["item." + i.rawValue, default: 0] += n
    }
    func addCoins(_ n: Int) { s.coins += n }

    /// Items to show in the hotbar, in content order.
    var hotbar: [(BItem, Int)] { BItem.allCases.compactMap { count($0) > 0 ? ($0, count($0)) : nil } }

    // MARK: - gathering

    var comboStep: Int { min(BloomContent.maxCombo, 1 + combo / BloomContent.hitsPerStep) }

    /// Registers a hit and returns the combo multiplier (x1...x5).
    func registerHit(now: TimeInterval) -> Int {
        combo = now - lastHit <= comboWindow ? combo + 1 : 1
        lastHit = now
        if comboStep > (s.stats["combo"] ?? 0) { s.stats["combo"] = comboStep }
        return comboStep
    }

    func tickCombo(now: TimeInterval) {
        if combo > 0 && now - lastHit > comboWindow { combo = 0 }
    }

    /// Rolls the drops of a destroyed gatherable. Extra items for the combo.
    func roll(_ k: GatherKind, mult: Int) -> [(BItem, Int)] {
        var out: [(BItem, Int)] = []
        for d in k.drops where Double.random(in: 0..<1) < d.chance {
            out.append((d.item, Int.random(in: d.min...d.max)))
        }
        if mult > 1, let first = out.first { out[0] = (first.0, first.1 + mult - 1) }
        if hasT("d4"), Double.random(in: 0..<1) < 0.15 { out = out.map { ($0.0, $0.1 * 2) } }
        if golden { out = out.map { ($0.0, $0.1 * 2) } }
        return out
    }

    /// Coins that fall out of a destroyed gatherable.
    func rollCoins(_ k: GatherKind, mult: Int) -> Int {
        let chance = (0.28 + 0.06 * Double(mult - 1) + (k.isStone ? 0.1 : 0)) * (hasT("t2") ? 1.5 : 1)
        let n = Double.random(in: 0..<1) < chance ? Int.random(in: 1...(k.isStone ? 3 : 2)) : 0
        return golden ? n * 2 : n
    }

    /// Returns new level if the xp made one.
    @discardableResult
    func gainXP(_ n0: Int) -> Int? {
        let n = pageDone(1) ? Int((Double(n0) * 1.15).rounded(.up)) : n0
        s.xp += n
        var up: Int?
        while s.xp >= BloomContent.xpToNext(s.level) {
            s.xp -= BloomContent.xpToNext(s.level)
            s.level += 1
            up = s.level
        }
        if let l = up {
            showToast(BloomToast(title: "Уровень \(l)!", subtitle: BloomContent.levelUnlockText[l] ?? "Новое очко таланта"))
            Sfx.play(.levelUp)
        }
        return up
    }

    // MARK: - building

    func canBuild(_ b: BuildKind) -> Bool { s.level >= b.unlockLevel && has(cost(b)) && !isBuilt(b) }
    func cost(_ b: BuildKind) -> Cost { hasT("c2") ? b.cost.map { ($0.0, Int((Double($0.1) * 0.8).rounded(.up))) } : b.cost }
    func isBuilt(_ b: BuildKind) -> Bool { s.buildings.contains { $0.kind == b } }

    func build(_ b: BuildKind) {
        guard canBuild(b), let cell = placeBuilding?(b) else { Sfx.play(.error); return }
        pay(cost(b))
        let pb = PlacedBuilding(kind: b, cell: cell)
        s.buildings.append(pb)
        panel = nil
        onBuildingPlaced?(pb)
        save()
    }

    // MARK: - crafting

    func queue(for b: BuildKind) -> CraftQueue? { s.queues[b.rawValue] }

    func craft(_ b: BuildKind, _ r: Recipe, times: Int) {
        let n = max(1, min(times, maxCraft(r)))
        guard has(r.cost, times: n) else { Sfx.play(.error); return }
        if var q = s.queues[b.rawValue], q.left > 0 {
            guard q.recipe == r.id else { Sfx.play(.error); return }
            q.left += n
            s.queues[b.rawValue] = q
        } else {
            s.queues[b.rawValue] = CraftQueue(recipe: r.id, left: n, progress: 0)
            progress[b.rawValue] = 0
        }
        pay(r.cost, times: n)
        Sfx.play(.select)
    }

    func maxCraft(_ r: Recipe) -> Int {
        r.cost.map { count($0.0) / $0.1 }.min() ?? 0
    }

    /// Advances crafting. Called by the scene each frame.
    func tick(dt: Double) {
        for b in BuildKind.allCases {
            guard let q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            var p = (progress[b.rawValue] ?? 0) + dt
            if p >= secs(r) {
                p -= secs(r)
                var nq = q
                nq.left -= 1
                if nq.left == 0 { p = 0 }
                s.queues[b.rawValue] = nq
                let n = hasT("c3") && Double.random(in: 0..<1) < 0.2 ? 2 : 1
                add(r.output, n)
                s.stats["craft." + r.output.rawValue, default: 0] += n
                onCrafted?(b, r.output, n > 1)
            }
            progress[b.rawValue] = p
        }
    }

    private func catchUp(seconds: Double) {
        guard seconds > 0 else { return }
        for b in BuildKind.allCases {
            guard var q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            let p = progress[b.rawValue] ?? 0
            let done = min(q.left, Int((p + seconds) / secs(r)))
            q.left -= done
            progress[b.rawValue] = q.left > 0 ? (p + seconds).truncatingRemainder(dividingBy: secs(r)) : 0
            add(r.output, done)
            s.queues[b.rawValue] = q
        }
    }

    // MARK: - anvil

    var nextPick: PickTier? { s.pick + 1 < BloomContent.picks.count ? BloomContent.picks[s.pick + 1] : nil }

    func forgePick() {
        guard let p = nextPick, has(p.cost) else { Sfx.play(.error); return }
        pay(p.cost)
        s.pick += 1
        s.lucky = Double.random(in: 0..<1) < luckyChance
        onCrafted?(.anvil, .iron_bar, s.lucky)
        showToast(BloomToast(title: s.lucky ? "Удачная ковка!" : p.title,
                           subtitle: s.lucky ? "\(p.title) +1 к удару" : "Удар: \(damage)"))
        Sfx.play(s.lucky ? .victory : .chest)
        save()
    }

    // MARK: - market

    func sell(_ i: BItem, all: Bool) {
        let n = all ? count(i) : min(count(i), 1)
        guard n > 0 else { return }
        s.inv[i.rawValue] = count(i) - n
        s.coins += n * sellPrice(i)
        Sfx.playThrottled(.coin, gap: 0.05)
    }

    // MARK: - islands

    func island(_ id: Int) -> BloomWorld.Island { world.islands[id] }

    func buy(_ id: Int) {
        let isl = island(id)
        guard !owned.contains(id), s.coins >= islandPrice(id) else { Sfx.play(.error); return }
        s.coins -= islandPrice(id)
        s.owned.append(id)
        panel = nil
        nearby = nil
        onIslandBought?(id)
        showToast(BloomToast(title: isl.name, subtitle: "Остров расцвёл!"))
        save()
    }

    // MARK: - stats & goals

    func gathered(_ k: GatherKind) {
        let key: String
        switch k {
        case .tree, .pine: key = "gather.tree"
        case .rock, .rock_iron, .rock_gold, .crystal: key = "gather.rock"
        case .bush_berry, .bush_cotton: key = "gather.bush"
        }
        s.stats[key, default: 0] += 1
    }

    func stat(_ key: String) -> Int {
        switch key {
        case "islands": return s.owned.count
        case "level": return s.level
        case "pick": return s.pick
        case "helpers": return s.helpers.count
        default:
            if key.hasPrefix("build."), let b = BuildKind(rawValue: String(key.dropFirst(6))) { return isBuilt(b) ? 1 : 0 }
            return s.stats[key] ?? 0
        }
    }

    var goal: Goal? { s.goal < BloomContent.goals.count ? BloomContent.goals[s.goal] : nil }
    var goalProgress: Int { goal.map { min($0.target, stat($0.key)) } ?? 0 }
    var goalDone: Bool { goal.map { stat($0.key) >= $0.target } ?? false }

    func claimGoal() {
        guard let g = goal, goalDone else { return }
        s.goal += 1
        s.coins += g.coins
        Sfx.play(.victory)
        onGoalClaimed?()
        showToast(BloomToast(title: "Цель выполнена!", subtitle: "+\(g.coins) монет" + (g.xp > 0 ? ", +\(g.xp) опыта" : "")))
        if g.xp > 0 { gainXP(g.xp) }
        save()
    }

    // MARK: - chests

    /// Loot of a treasure chest: coins and a few items of the islands you own.
    func openChest() -> (coins: Int, items: [(BItem, Int)]) {
        s.stats["chest", default: 0] += 1
        let tier = s.owned.count
        let coins = Int.random(in: 10...20) + tier * 8
        var pool: [BItem] = [.wood, .stone, .berry, .flower]
        if s.owned.contains(1) || s.owned.contains(3) { pool.append(.cotton) }
        if s.owned.contains(2) { pool += [.iron_ore, .brick] }
        if s.owned.contains(4) { pool += [.gold_ore, .iron_bar] }
        if s.owned.contains(5) { pool.append(.crystal) }
        var items: [(BItem, Int)] = []
        for i in pool.shuffled().prefix(3) {
            let n = [.crystal, .gold_ore, .iron_bar].contains(i) ? Int.random(in: 1...2) : Int.random(in: 3...6)
            items.append((i, n))
        }
        gainXP(6 + tier * 2)
        Sfx.play(.chest)
        return (coins, items)
    }

    // MARK: - helpers

    var helpers: [String] { s.helpers }
    var helperCost: Cost {
        let c = BloomContent.helperCost(s.helpers.count)
        return hasT("h1") ? c.map { ($0.0, Int((Double($0.1) * 0.7).rounded(.up))) } : c
    }
    var maxHelpers: Int { BloomContent.maxHelpers + (hasT("h4") ? 1 : 0) }
    var canGrowHelper: Bool { s.helpers.count < maxHelpers && has(helperCost) }

    func growHelper() {
        guard canGrowHelper else { Sfx.play(.error); return }
        pay(helperCost)
        let free = BloomContent.helperColors.filter { !s.helpers.contains($0) }
        let c = free.randomElement() ?? "pink"
        s.helpers.append(c)
        onHelperAdded?(c)
        showToast(BloomToast(title: "Новый помощник!", subtitle: (BloomContent.helperNames[c] ?? "Блумлинг") + " будет добывать с тобой"))
        Sfx.play(.levelUp)
        panel = nil
        save()
    }

    // MARK: - talents

    @Published var goldenUntil: Date?
    var golden: Bool { (goldenUntil ?? .distantPast) > Date() }
    var onTalentsChanged: (() -> Void)?

    func hasT(_ id: String) -> Bool { s.talents.contains(id) }
    var talentPoints: Int {
        max(0, (s.level - 1) - s.talents.reduce(0) { $0 + BloomTalents.talent($1).cost })
    }
    func canLearn(_ t: Talent) -> Bool {
        !hasT(t.id) && (t.requires.map(hasT) ?? true) && talentPoints >= t.cost
    }
    func learn(_ t: Talent) {
        guard canLearn(t) else { Sfx.play(.error); return }
        s.talents.append(t.id)
        Sfx.play(.levelUp)
        onTalentsChanged?()
        save()
    }

    var comboWindow: Double { BloomContent.comboWindow + (hasT("d3") ? 0.4 : 0) }
    var critChance: Double { BloomContent.critChance + (hasT("d2") ? 0.06 : 0) }
    var luckyChance: Double { BloomContent.luckyChance + (hasT("c4") ? 0.25 : 0) }
    func secs(_ r: Recipe) -> Double { r.seconds * (hasT("c1") ? 0.75 : 1) * (hasT("c5") ? 0.7 : 1) }
    func sellPrice(_ i: BItem) -> Int { hasT("t1") ? Int((Double(i.price) * 1.25).rounded(.up)) : i.price }
    func islandPrice(_ id: Int) -> Int {
        let p = island(id).price
        return hasT("t4") ? Int((Double(p) * 0.8).rounded()) : p
    }
    var chestChance: Double { BloomContent.chestChance * (hasT("t3") ? 2 : 1) * (golden ? 2 : 1) }
    var respawnInterval: Double { hasT("b2") ? 2.2 / 1.4 : 2.2 }
    var flowerFactor: Int { hasT("b1") ? 2 : 1 }
    var goldenDuration: Double { GoldenHour.duration * (hasT("b4") ? 1.5 : 1) }
    var helperSpeed: CGFloat { hasT("h2") ? 1.4 : 1 }
    var helperDamage: Int { hasT("h3") ? 2 : 1 }
    var runSpeed: CGFloat { pageDone(0) ? 1.15 : 1 }

    // MARK: - album

    var finds: [String: Int] { s.finds }
    func pageDone(_ i: Int) -> Bool { BloomAlbum.pages[i].finds.allSatisfy { (s.finds[$0.id] ?? 0) > 0 } }

    /// Maybe a rare find from a destroyed gatherable: (id, isNew).
    func rollFind(_ k: GatherKind) -> (String, Bool)? {
        let chance = BloomAlbum.baseChance * (hasT("t5") ? 2 : 1) * (golden ? 1.5 : 1)
        guard Double.random(in: 0..<1) < chance else { return nil }
        let page = BloomAlbum.page(for: k)
        let f = BloomAlbum.pages[page].finds.randomElement()!.id
        let isNew = (s.finds[f] ?? 0) == 0
        s.finds[f, default: 0] += 1
        if isNew {
            let got = BloomAlbum.pages[page].finds.filter { (s.finds[$0.id] ?? 0) > 0 }.count
            if pageDone(page) {
                showToast(BloomToast(title: "Страница «\(BloomAlbum.pages[page].title)» собрана!", subtitle: BloomAlbum.pages[page].bonus))
                Sfx.play(.victory)
            } else {
                showToast(BloomToast(title: "Находка: \(BloomAlbum.title(f))", subtitle: "\(BloomAlbum.pages[page].title): \(got)/5"))
            }
        } else {
            s.coins += BloomAlbum.duplicateCoins
        }
        s.stats["finds", default: 0] += 1
        return (f, isNew)
    }

    // MARK: - toasts (one at a time, the rest wait their turn)

    private var toastQueue: [BloomToast] = []

    func showToast(_ t: BloomToast) {
        if toast == nil { toast = t } else { toastQueue.append(t) }
    }

    func nextToast() {
        toast = toastQueue.isEmpty ? nil : toastQueue.removeFirst()
    }

    // MARK: - save

    func save() {
        var v = s
        v.savedAt = Date()
        for (k, p) in progress { v.queues[k]?.progress = p }
        if let d = try? JSONEncoder().encode(v) { UserDefaults.standard.set(d, forKey: key) }
    }
}
